// ============================================
// TABLE CREATION & SETUP SQL PREPARATION
// ============================================

// Get config from previous node
const config = $input.first().json;
const webhookData = $('Webhook - Receive OTP Request').first().json;

// SQL to create all required tables
const createTablesSql = `
-- Create users table if not exists
CREATE TABLE IF NOT EXISTS users (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  email VARCHAR(255) UNIQUE NOT NULL,
  is_verified BOOLEAN DEFAULT FALSE,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
  updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- Create otp_codes table if not exists
CREATE TABLE IF NOT EXISTS otp_codes (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  email VARCHAR(255) NOT NULL,
  otp_code VARCHAR(6) NOT NULL,
  expires_at TIMESTAMP WITH TIME ZONE NOT NULL,
  is_used BOOLEAN DEFAULT FALSE,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- Create user_sessions table if not exists
CREATE TABLE IF NOT EXISTS user_sessions (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id UUID REFERENCES users(id) ON DELETE CASCADE,
  session_token VARCHAR(255) UNIQUE NOT NULL,
  expires_at TIMESTAMP WITH TIME ZONE NOT NULL,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- Create news_categories table if not exists
CREATE TABLE IF NOT EXISTS news_categories (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  name VARCHAR(100) NOT NULL,
  name_tamil VARCHAR(100) NOT NULL,
  description TEXT,
  description_tamil TEXT,
  schedule VARCHAR(50) NOT NULL,
  delivery_time TIME,
  delivery_day VARCHAR(20),
  is_active BOOLEAN DEFAULT TRUE,
  icon VARCHAR(50),
  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- Create subscriptions table if not exists
CREATE TABLE IF NOT EXISTS subscriptions (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id UUID REFERENCES users(id) ON DELETE CASCADE,
  category_id UUID REFERENCES news_categories(id),
  is_active BOOLEAN DEFAULT TRUE,
  subscribed_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
  unsubscribed_at TIMESTAMP WITH TIME ZONE,
  UNIQUE(user_id, category_id)
);

-- Create indexes if not exists
CREATE INDEX IF NOT EXISTS idx_otp_codes_email ON otp_codes(email);
CREATE INDEX IF NOT EXISTS idx_otp_codes_expires ON otp_codes(expires_at);
CREATE INDEX IF NOT EXISTS idx_user_sessions_token ON user_sessions(session_token);
CREATE INDEX IF NOT EXISTS idx_user_sessions_expires ON user_sessions(expires_at);
CREATE INDEX IF NOT EXISTS idx_subscriptions_user ON subscriptions(user_id);
`;

// Seed data SQL
const seedCategoriesSql = `
INSERT INTO news_categories (name, name_tamil, description, description_tamil, schedule, delivery_time, icon)
SELECT 'Daily Tamil News', 'தினசரி தமிழ் செய்திகள்', 'Get the latest Tamil news every morning', 'ஒவ்வொரு காலையும் சமீபத்திய தமிழ் செய்திகளைப் பெறுங்கள்', 'daily', '06:00'::TIME, 'newspaper'
WHERE NOT EXISTS (SELECT 1 FROM news_categories WHERE name = 'Daily Tamil News');

INSERT INTO news_categories (name, name_tamil, description, description_tamil, schedule, delivery_time, icon)
SELECT 'Weekly Tech Updates', 'வாராந்திர தொழில்நுட்ப செய்திகள்', 'Technology news and updates every Monday', 'ஒவ்வொரு திங்களும் தொழில்நுட்ப செய்திகள்', 'weekly', '09:00'::TIME, 'cpu'
WHERE NOT EXISTS (SELECT 1 FROM news_categories WHERE name = 'Weekly Tech Updates');

INSERT INTO news_categories (name, name_tamil, description, description_tamil, schedule, delivery_time, icon)
SELECT 'Monthly Cinema Digest', 'மாதாந்திர சினிமா செய்திகள்', 'Tamil cinema news and reviews monthly', 'மாதாந்திர தமிழ் சினிமா செய்திகள் மற்றும் விமர்சனங்கள்', 'monthly', '10:00'::TIME, 'film'
WHERE NOT EXISTS (SELECT 1 FROM news_categories WHERE name = 'Monthly Cinema Digest');

INSERT INTO news_categories (name, name_tamil, description, description_tamil, schedule, delivery_time, icon)
SELECT 'Sports Weekly', 'வாராந்திர விளையாட்டு செய்திகள்', 'Sports news every Saturday', 'ஒவ்வொரு சனிக்கிழமையும் விளையாட்டு செய்திகள்', 'weekly', '08:00'::TIME, 'trophy'
WHERE NOT EXISTS (SELECT 1 FROM news_categories WHERE name = 'Sports Weekly');

INSERT INTO news_categories (name, name_tamil, description, description_tamil, schedule, delivery_time, icon)
SELECT 'Business & Finance', 'வணிகம் மற்றும் நிதி', 'Daily business and market updates', 'தினசரி வணிக மற்றும் சந்தை செய்திகள்', 'daily', '07:00'::TIME, 'trending-up'
WHERE NOT EXISTS (SELECT 1 FROM news_categories WHERE name = 'Business & Finance');
`;

return [{
  json: {
    // Pass config forward
    supabase_url: config.SUPABASE_URL,
    supabase_key: config.SUPABASE_SERVICE_KEY,
    resend_api_key: config.RESEND_API_KEY,
    from_email: config.FROM_EMAIL,
    // SQL statements
    create_tables_sql: createTablesSql,
    seed_categories_sql: seedCategoriesSql,
    // Original request
    request_body: webhookData.body
  }
}];

// Get data from previous nodes
const prepareData = $('Prepare Setup SQLs').first().json;

// Continue regardless of SQL result (tables may already exist)
return [{
  json: {
    setup_attempted: true,
    supabase_url: prepareData.supabase_url,
    supabase_key: prepareData.supabase_key,
    resend_api_key: prepareData.resend_api_key,
    from_email: prepareData.from_email,
    seed_categories_sql: prepareData.seed_categories_sql,
    request_body: prepareData.request_body
  }
}];

// ============================================
// GENERATE OTP CODE
// ============================================

// Get data from Process Create Result node
const prevData = $('Process Create Result').first().json;
const body = prevData.request_body;
const email = body?.email;

// Validate email format
const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
if (!email || !emailRegex.test(email)) {
  return [{
    json: {
      valid: false,
      error: 'Invalid email address',
      error_tamil: 'தவறான மின்னஞ்சல் முகவரி'
    }
  }];
}

// Generate 6-digit OTP
const otp = Math.floor(100000 + Math.random() * 900000).toString();

// Calculate expiry time (10 minutes from now)
const expiresAt = new Date(Date.now() + 10 * 60 * 1000).toISOString();

return [{
  json: {
    valid: true,
    email: email,
    otp: otp,
    expires_at: expiresAt,
    created_at: new Date().toISOString(),
    // Pass config forward
    supabase_url: prevData.supabase_url,
    supabase_key: prevData.supabase_key,
    resend_api_key: prevData.resend_api_key,
    from_email: prevData.from_email
  }
}];

